/**
 * ISO Survey 2025 data for the lead-capture report.
 *
 * `datos.json` and `normas.json` are generated by the design repo
 * (bocetos/iso-survey-2025-correo/_build_v3.py) straight from ISO's files; no
 * figure is typed by hand here. Each country row is
 * { a2, es, en, r, d: { [standard]: [certificates, sites, certificates2024] } }.
 */
import datos from "./datos.json";
import normas from "./normas.json";

export type Locale = "es" | "en";

export interface Country {
  n: string;
  a2: string;
  num: string | null;
  es: string;
  en: string;
  r: string;
  d: Record<string, [number, number, number | null]>;
}

export const COUNTRIES = datos.paises as unknown as Country[];
export const STANDARDS = datos.normas as string[];
export const LABEL = normas.rotulo as Record<string, string>;
export const TOPIC = normas.tema as Record<Locale, Record<string, string>>;
export const COLOR = normas.color as Record<string, string>;

const BY_A2 = new Map(COUNTRIES.map((c) => [c.a2, c]));

export const DEFAULT_COUNTRY: Record<Locale, string> = { es: "MX", en: "US" };

export const REGION: Record<string, [string, string]> = {
  LA: ["América Latina y el Caribe", "Latin America & the Caribbean"],
  NA: ["Norteamérica", "North America"],
  EU: ["Europa", "Europe"],
  AS: ["Asia", "Asia"],
  AF: ["África", "Africa"],
  OC: ["Oceanía", "Oceania"],
  AN: ["Antártida", "Antarctica"],
};

export function countryByA2(a2: string | null | undefined): Country | undefined {
  return a2 ? BY_A2.get(a2.toUpperCase()) : undefined;
}

export function certificates(c: Country, k: string): number {
  return c.d[k]?.[0] ?? 0;
}

/** Below this many certificates in 2024 a percentage is noise (3 → 9 = +200%). */
export const MIN_BASE = 20;

export function growth(c: Country, k: string): number | null {
  const row = c.d[k];
  if (!row || row[2] == null || row[2] < MIN_BASE) return null;
  return ((row[0] - row[2]) / row[2]) * 100;
}

/** [rank, number of countries that hold the standard], within a set of countries. */
export function rank(c: Country, k: string, among: Country[] = COUNTRIES): [number, number] {
  const values = among.map((x) => certificates(x, k)).filter((v) => v > 0).sort((a, b) => b - a);
  const v = certificates(c, k);
  return [v ? values.indexOf(v) + 1 : 0, values.length];
}

export function regionRank(c: Country, k: string): [number, number] {
  return rank(c, k, COUNTRIES.filter((x) => x.r === c.r));
}

export function ordinal(n: number, locale: Locale): string {
  if (locale === "es") return `${n}.º`;
  const tail = n % 100 >= 11 && n % 100 <= 13 ? "th" : ({ 1: "st", 2: "nd", 3: "rd" } as Record<number, string>)[n % 10] ?? "th";
  return `${n}${tail}`;
}

export function formatNumber(n: number): string {
  return new Intl.NumberFormat("en-US").format(Math.round(n));
}

// ---------------------------------------------------------------- country from free text

function fold(s: string): string {
  return s
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9 ]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

// What people actually type, beyond the official names.
const ALIASES: Record<string, string> = {
  usa: "US", eeuu: "US", "ee uu": "US", "estados unidos": "US", "united states": "US", "u s a": "US",
  mexico: "MX", mex: "MX", mx: "MX",
  uk: "GB", "reino unido": "GB", inglaterra: "GB", england: "GB",
  espana: "ES", brasil: "BR", "republica dominicana": "DO", "corea del sur": "KR", "south korea": "KR",
};

const NAME_INDEX: Array<[string, string]> = (() => {
  const pairs = new Map<string, string>();
  for (const c of COUNTRIES) {
    pairs.set(fold(c.es), c.a2);
    pairs.set(fold(c.en), c.a2);
    pairs.set(fold(c.n), c.a2);
  }
  for (const [k, v] of Object.entries(ALIASES)) pairs.set(k, v);
  // Longest first, so "republica dominicana" wins over "dominica".
  return [...pairs.entries()].filter(([k]) => k.length >= 2).sort((a, b) => b[0].length - a[0].length);
})();

/** The country named in a message, or null. Matches whole words only. */
export function findCountry(text: string): string | null {
  const t = ` ${fold(text)} `;
  for (const [name, a2] of NAME_INDEX) {
    if (t.includes(` ${name} `)) return a2;
  }
  return null;
}

// ---------------------------------------------------------------- email from free text

const EMAIL_RE = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/;

export function findEmail(text: string): string | null {
  const m = text.match(EMAIL_RE);
  return m ? m[0].replace(/\.+$/, "").toLowerCase() : null;
}

/** The text without any email address in it (so ".mx" in a domain is not a country). */
export function stripEmails(text: string): string {
  return text.replace(new RegExp(EMAIL_RE.source, "g"), " ");
}

export function isEmail(text: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(text);
}
